$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$mp=Join-Path $root 'port-changes.json';$m=Get-Content $mp -Raw|ConvertFrom-Json
$targets=@(
 [pscustomobject]@{rel='content/logistics/stockTicker/StockTickerBlock.java';changes=@(
  [pscustomobject]@{from='import com.simibubi.create.AllBlockEntityTypes;';to="import com.mojang.serialization.MapCodec;`nimport com.simibubi.create.AllBlockEntityTypes;"},
  [pscustomobject]@{from='import net.minecraft.world.InteractionResult;';to='import net.minecraft.world.ItemInteractionResult;'},
  [pscustomobject]@{from="public class StockTickerBlock extends HorizontalDirectionalBlock implements IBE<StockTickerBlockEntity>, IWrenchable {";to="public class StockTickerBlock extends HorizontalDirectionalBlock implements IBE<StockTickerBlockEntity>, IWrenchable {`n`n`tpublic static final MapCodec<StockTickerBlock> CODEC = simpleCodec(StockTickerBlock::new);"},
  [pscustomobject]@{from="public InteractionResult use(BlockState pState, Level pLevel, BlockPos pPos, Player pPlayer, InteractionHand pHand,`n`t`tBlockHitResult pHit) {`n`t`tif (pPlayer != null && pPlayer.getItemInHand(pHand)`n`t`t`t.getItem() instanceof LogisticallyLinkedBlockItem)`n`t`t`treturn InteractionResult.PASS;`n`n`t`treturn onBlockEntityUse(pLevel, pPos, stbe -> {";to="protected ItemInteractionResult useItemOn(ItemStack stack, BlockState pState, Level pLevel, BlockPos pPos, Player pPlayer, InteractionHand pHand,`n`t`tBlockHitResult pHit) {`n`t`tif (stack.getItem() instanceof LogisticallyLinkedBlockItem)`n`t`t`treturn ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;`n`n`t`treturn onBlockEntityUseItemOn(pLevel, pPos, stbe -> {"},
  [pscustomobject]@{from='return InteractionResult.SUCCESS;';to='return ItemInteractionResult.SUCCESS;'},
  [pscustomobject]@{from="public boolean isPathfindable(BlockState pState, BlockGetter pLevel, BlockPos pPos, PathComputationType pType) {`n`t`treturn false;`n`t}";to="protected boolean isPathfindable(BlockState pState, PathComputationType pType) {`n`t`treturn false;`n`t}`n`n`t@Override`n`tprotected MapCodec<? extends HorizontalDirectionalBlock> codec() {`n`t`treturn CODEC;`n`t}"}
 );status='Original Stock Ticker payment/menu interaction adapted to Minecraft 1.21.1 item interaction, pathfinding, and block codec APIs.'},
 [pscustomobject]@{rel='content/logistics/packagePort/postbox/PostboxBlock.java';changes=@(
  [pscustomobject]@{from='import com.simibubi.create.AllBlockEntityTypes;';to="import org.jetbrains.annotations.NotNull;`n`nimport com.mojang.serialization.MapCodec;`nimport com.mojang.serialization.codecs.RecordCodecBuilder;`nimport com.simibubi.create.AllBlockEntityTypes;"},
  [pscustomobject]@{from='import net.minecraft.world.InteractionHand;';to=''},
  [pscustomobject]@{from='import net.minecraft.world.level.block.state.BlockState;';to="import net.minecraft.world.level.block.state.BlockBehaviour;`nimport net.minecraft.world.level.block.state.BlockState;"},
  [pscustomobject]@{from="`timplements IBE<PostboxBlockEntity>, IWrenchable, ProperWaterloggedBlock {";to="`timplements IBE<PostboxBlockEntity>, IWrenchable, ProperWaterloggedBlock {`n`tpublic static MapCodec<PostboxBlock> CODEC = RecordCodecBuilder.mapCodec(instance -> instance.group(`n`t`tBlockBehaviour.propertiesCodec(),`n`t`tDyeColor.CODEC.fieldOf(`"color`").forGetter(PostboxBlock::getColor)`n`t).apply(instance, PostboxBlock::new));"},
  [pscustomobject]@{from="public InteractionResult use(BlockState pState, Level pLevel, BlockPos pPos, Player pPlayer, InteractionHand pHand,`n`t`tBlockHitResult pHit) {`n`t`treturn onBlockEntityUse(pLevel, pPos, be -> be.use(pPlayer));`n`t}";to="protected InteractionResult useWithoutItem(BlockState state, Level level, BlockPos pos, Player player, BlockHitResult hitResult) {`n`t`treturn onBlockEntityUse(level, pos, be -> be.use(player).result());`n`t}"},
  [pscustomobject]@{from="public boolean isPathfindable(BlockState state, BlockGetter reader, BlockPos pos, PathComputationType type) {`n`t`treturn false;`n`t}";to="protected boolean isPathfindable(BlockState state, PathComputationType type) {`n`t`treturn false;`n`t}`n`n`t@Override`n`tprotected @NotNull MapCodec<? extends HorizontalDirectionalBlock> codec() {`n`t`treturn CODEC;`n`t}"}
 );status='Original Postbox interaction/comparator behavior adapted to Minecraft 1.21.1 block codec and no-item interaction APIs.'},
 [pscustomobject]@{rel='content/logistics/tableCloth/TableClothBlock.java';changes=@(
  [pscustomobject]@{from='import net.minecraft.world.InteractionResult;';to='import net.minecraft.world.ItemInteractionResult;'},
  [pscustomobject]@{from="public InteractionResult use(BlockState state, Level world, BlockPos pos, Player player, InteractionHand hand,`n`t`tBlockHitResult ray) {";to="protected ItemInteractionResult useItemOn(ItemStack stack, BlockState state, Level world, BlockPos pos, Player player, InteractionHand hand,`n`t`tBlockHitResult ray) {"},
  [pscustomobject]@{from='return InteractionResult.PASS;';to='return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;'},
  [pscustomobject]@{from='return InteractionResult.SUCCESS;';to='return ItemInteractionResult.SUCCESS;'},
  [pscustomobject]@{from='return onBlockEntityUse(world, pos, dcbe -> dcbe.use(player, ray));';to='return onBlockEntityUseItemOn(world, pos, dcbe -> dcbe.use(player, ray));'}
 );status='Original Table Cloth placement/shop interaction adapted to Minecraft 1.21.1 item interaction APIs.'}
)
foreach($t in $targets){$p=Join-Path $root "source/fabric/src/main/java/com/simibubi/create/$($t.rel)";$x=[IO.File]::ReadAllText($p);foreach($c in $t.changes){if(-not$x.Contains($c.from)){throw "Logistics block anchor missing in $($t.rel): $($c.from)"};$x=$x.Replace($c.from,$c.to)};[IO.File]::WriteAllText($p,$x,[Text.UTF8Encoding]::new($false));$e=$m.files|Where-Object path -eq $t.rel;$e.changes=@($e.changes)+$t.changes;if($e.PSObject.Properties.Name -contains 'status'){$e.status=$t.status}else{$e|Add-Member -NotePropertyName status -NotePropertyValue $t.status}}
$m|ConvertTo-Json -Depth 20|Set-Content $mp -Encoding utf8;Write-Output 'Adapted native logistics blocks to Minecraft 1.21.1 block APIs.'
